from typing import List, Optional

from pydantic import BaseModel, Field, ValidationError, validator


class Address(BaseModel):
    city: str
    zip: str = Field("00000", regex=r"^\d{5}$")


class User(BaseModel):
    name: str
    email: str = Field(..., regex=r"^[^@\s]+@[^@\s]+$")
    age: int = 0
    nickname: Optional[str]
    address: Optional[Address] = None
    tags: List[str] = []

    @validator("name")
    def name_not_blank(cls, v):
        if not v.strip():
            raise ValueError("name must not be blank")
        return v.title()

    @validator("tags", each_item=True)
    def tag_lower(cls, v):
        return v.lower()

    class Config:
        anystr_strip_whitespace = True


def load_user(data):
    return User.parse_obj(data)


def load_user_json(raw):
    return User.parse_raw(raw)


def dump_user(user):
    return user.dict(exclude_none=True)


def user_json(user):
    return user.json()


def birthday(user):
    return user.copy(update={"age": user.age + 1})


def field_names():
    return list(User.__fields__)


def try_load(data):
    try:
        return User.parse_obj(data)
    except ValidationError:
        return None

