import json

from app.core import (
    birthday, dump_user, field_names, load_user, load_user_json, try_load,
    user_json,
)

DATA = {"name": "  ada lovelace ", "email": "ada@example.org", "age": 36,
        "tags": ["Math", "ENGINE"], "address": {"city": "London", "zip": "12345"}}


def test_load_user():
    u = load_user(DATA)
    assert u.name == "Ada Lovelace"
    assert u.tags == ["math", "engine"]
    assert u.address.city == "London"


def test_load_user_json():
    u = load_user_json('{"name": "bob", "email": "b@example.com"}')
    assert u.name == "Bob"
    assert u.age == 0


def test_dump_user():
    d = dump_user(load_user(DATA))
    assert d["name"] == "Ada Lovelace"
    assert "nickname" not in d
    assert d["address"] == {"city": "London", "zip": "12345"}


def test_user_json_roundtrip():
    u = load_user(DATA)
    assert json.loads(user_json(u))["age"] == 36
    assert load_user_json(user_json(u)) == u


def test_birthday():
    assert birthday(load_user(DATA)).age == 37


def test_fields():
    assert field_names() == ["name", "email", "age", "nickname", "address", "tags"]


def test_try_load_rejects_bad_email():
    assert try_load({"name": "x", "email": "nope"}) is None

